'use strict';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=Object.fromEntries(DATA.countries.map(c=>[c.code,c.name]));
const source=(id)=>{const s=DATA.sources.find(s=>s.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.agency)} · ${esc(s.title)}</a>`:''};
const fmt=n=>Number(n).toLocaleString('en-AU',{maximumFractionDigits:2});
const extra=i=>DATA.extensions.filter(r=>r.indicator===i);
const dataFor=i=>DATA.observations.filter(r=>r.indicator===i);
const table=(heads,rows,caption='')=>`<div class="table-wrap"><table>${caption?`<caption>${caption}</caption>`:''}<thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const top=(n,title,intro)=>`<div class="eyebrow">${n}</div><h1>${title}</h1><p class="intro">${intro}</p>`;
function lineChart(series,labels,{title='Chart',zero=false}={}){const w=760,h=300,l=58,r=22,t=22,b=48;const vals=series.flatMap(s=>s.values).filter(Number.isFinite);let lo=Math.min(...vals),hi=Math.max(...vals);if(zero){lo=Math.min(0,lo);hi=Math.max(0,hi)}if(!vals.length)return '<p>No chart data available.</p>';const pad=Math.max((hi-lo)*.1,.2);lo-=pad;hi+=pad;const x=i=>l+i*(w-l-r)/Math.max(1,labels.length-1),y=v=>h-b-(v-lo)/(hi-lo)*(h-t-b);let out=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;for(let k=0;k<5;k++){const v=lo+(hi-lo)*k/4;out+=`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#dce5eb"/><text x="${l-10}" y="${y(v)+5}" text-anchor="end">${v.toFixed(1)}</text>`}labels.forEach((v,i)=>{if(labels.length<9||i===0||i===labels.length-1||i%5===0)out+=`<text x="${x(i)}" y="${h-14}" text-anchor="middle">${esc(v)}</text>`});series.forEach((s,j)=>{const c=s.color||['#005be5','#007c78','#ae4d17'][j%3];let segment=[];const flush=()=>{if(segment.length)out+=`<polyline fill="none" stroke="${c}" stroke-width="3" ${s.dashed?'stroke-dasharray="7 5"':''} points="${segment.join(' ')}"/>`;segment=[]};s.values.forEach((v,i)=>{if(!Number.isFinite(v)){flush();return}segment.push(`${x(i)},${y(v)}`);out+=`<circle cx="${x(i)}" cy="${y(v)}" r="${s.values.length<15?4:2}" fill="${c}"><title>${esc(s.name)} · ${esc(labels[i])}: ${v.toFixed(2)}</title></circle>`});flush()});return out+'</svg>'}
function dashboard(){return top('01 / Economic dashboard','A bigger economy. A better life?','Start with three different questions: how much are we producing, how much per person, and how much per hour of work?')+`<div class="cards"><article class="card"><span class="tag">OFFICIAL OBSERVATION</span><h3>Real GDP</h3><div class="metric blue">+2.1%</div><p class="small">Year to June 2026<br>Total output of the economy</p></article><article class="card"><span class="tag">OFFICIAL OBSERVATION</span><h3>Real GDP per person</h3><div class="metric">+0.7%</div><p class="small">Year to June 2026<br>Output relative to population</p></article><article class="card"><span class="tag">OFFICIAL OBSERVATION</span><h3>Output per hour</h3><div class="metric rust">−0.2%</div><p class="small">Year to June 2026<br>Whole-economy labour productivity</p></article></div><p class="source">${source('abs_q')}. These are through-year changes, not quarterly or annual-average changes.</p><div class="split"><section class="panel"><h2>Growth has more than one source</h2><p class="small">Quarter-on-quarter change, %. Seasonally adjusted.</p><div class="legend"><span>Real GDP</span><span>GDP per hour</span></div>${lineChart([{name:'Real GDP',values:dataFor('gdp_qoq').map(r=>r.value)},{name:'GDP per hour',values:dataFor('productivity_qoq').map(r=>r.value)}],dataFor('gdp_qoq').map(r=>r.period),{title:'Quarterly changes in real GDP and labour productivity',zero:true})}<p class="source">${source('abs_q')}. Zero includes changes rounded to zero.</p></section><section class="panel"><h2>Why your household may feel different</h2><p>Total output can grow because there are more people or more hours worked. Productivity asks what each hour produces.</p><p>What you can afford also depends on wages, taxes, transfers, housing costs and how income is shared.</p><a href="#learn">See the productivity explainer →</a><hr><span class="tag gap">COVERAGE</span><p class="small">This edition contains verified data extracts. Annual international histories and the parliamentary occupation roster are now populated. Hourly productivity coverage, employer-sector verification and costed party comparisons remain incomplete.</p></section></div><section class="panel"><h2>Australia over five financial years</h2><p class="small">Annual changes, %. October 2025 data vintage, retained separately from the revised quarterly release.</p>${table(['Financial year','Real GDP','GDP per person','Output per hour'],dataFor('gdp_growth').map((r,i)=>[r.period,r.value.toFixed(1),dataFor('gdp_per_capita_growth')[i].value.toFixed(1),dataFor('productivity_growth')[i].value.toFixed(1)]))}<p class="source">${source('abs_a')}</p><a class="button" href="data/observations.csv" download>Download all observations · CSV</a></section>`}
function learn(){return top('02 / The essentials','Productivity is about what an hour can do.','Better tools, skills, organisation and infrastructure can make the same amount of work go further.')+`<div class="formula">Output per person = output per hour × hours worked per person</div><div class="steps"><article class="step"><b>01 · Produce more value</b>A bakery’s new oven makes more bread per hour. A clinic’s better scheduling reduces wasted appointments.</article><article class="step"><b>02 · Decide who benefits</b>Gains can become higher wages, lower prices, larger profits, better service or more leisure. Competition and institutions affect the split.</article><article class="step"><b>03 · Check living standards</b>Measure real household income, access to services and time as well as GDP. More output alone does not tell us who is better off.</article></div><section class="panel"><h2>Small differences accumulate</h2><p>A teaching illustration: start output per hour at 100. Change the annual growth assumptions to see their effects. These are not forecasts for a party or country.</p><div class="tools"><label>Path A annual productivity growth (%)<input id="growth-a" type="number" min="-2" max="5" step="0.1" value="0.5"></label><label>Path B annual productivity growth (%)<input id="growth-b" type="number" min="-2" max="5" step="0.1" value="1.5"></label><label>Years<input id="years" type="number" min="1" max="40" step="1" value="20"></label></div><div id="growth-output" aria-live="polite"></div><p class="small">Formula: 100 × (1 + annual growth / 100)<sup>years</sup>. Holds work hours, population and distribution outside the calculation.</p><button id="export-chart">Download this infographic · SVG</button></section><section class="panel"><h2>Six distinctions that prevent bad conclusions</h2>${table(['Distinction','Why it matters'],[['Nominal vs real','A dollar increase can reflect prices rather than more goods or services.'],['Total vs per person','Population growth can lift total GDP without lifting output per person.'],['Average vs median','An average can rise while a typical household gains little.'],['Productivity vs effort','Output per hour reflects capital, technology and organisation as well as workers.'],['Measured output vs social value','Unpaid care and quality improvements may be poorly captured. A paid care job is not inherently unproductive.'],['Price level vs inflation','Slower inflation means prices rise more slowly; it does not mean prices return to their old level.']])}<p class="source">Productivity measure: ${source('oecd_p')}; household income: ${source('income')}.</p></section><section class="panel"><h2>Capitalism and socialism: unpack the label</h2><p>Use separate, measurable dimensions: private and public ownership, competition, taxation, redistribution, regulation, and the delivery of services. A country can combine competitive private businesses with extensive public insurance.</p><p>The transcript’s Denmark–United States contrast is a question to test. Track entrepreneurship and productivity alongside poverty, household security and mobility.</p><p class="source">${source('denmark')} · ${source('wealth')}</p></section>`}
function countries(){return top('03 / Country comparisons','38 countries. Explore the evidence.','Choose a measure and comparison year. Inspect a country’s full available history, then follow its source or download the data.')+`<div class="coverage"><span>${DATA.panel.length.toLocaleString()} annual observations</span><span>20 measures</span><span>2000–2025 requested</span><span>38 member countries</span></div><div class="tools"><label>Measure<select id="panel-metric">${DATA.metrics.map(m=>`<option value="${m.code}" ${m.code==='NY.GDP.PCAP.PP.KD'?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Year<select id="panel-year">${Array.from({length:26},(_,i)=>2025-i).map(y=>`<option ${y===2024?'selected':''}>${y}</option>`).join('')}</select></label><label>Find a country<input id="country-search" type="search" placeholder="Australia, Denmark…"></label><label>Show<select id="country-scope"><option value="all">All countries</option><option value="loaded">With data in chosen year</option></select></label></div><div id="country-table"></div><section class="panel"><h2>Country history</h2><div class="tools"><label>Country<select id="history-country">${DATA.countries.map(c=>`<option value="${c.code}" ${c.code==='AUS'?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><a class="button" href="data/panel.csv" download>Download full panel · CSV</a></div><div id="country-history"></div></section><section class="panel"><h2>Output per hour: separately sourced OECD extracts</h2><p>The 20-series panel includes output per employed person, which also reflects working hours. It does not replace output per hour. The OECD bulk hourly series remains unavailable in this edition.</p>${table(['Country','Year','Constant 2020 USD PPP/hour'],dataFor('productivity_level').map(r=>[esc(names[r.country]),r.period,r.value.toFixed(1)]))}<p class="source">${source('oecd_p')}</p></section><section class="panel"><h2>Read comparisons with their definitions</h2><p>World Bank WDI harmonises national and international sources, including ILO modelled labour estimates. Gini surveys differ in income/consumption concept. Central-government debt, GFS expenses and taxes do not constitute a harmonised all-government fiscal comparison. Tax revenue excludes most social contributions; net energy imports can be negative for exporters.</p><p>Values are shown for the selected year only. No filling, interpolation, mixed-year ranking or missing-as-zero treatment is applied. Each country’s latest available year is shown separately.</p></section>`}
function ndis(){const obs=dataFor('ndis_cost');return top('04 / NDIS & the economy','Follow the money. Count the outcomes.','Measure the cost of disability support, the integrity of payments, and the effects on participants, carers, workers and taxpayers.')+`<div class="cards"><article class="card"><span class="tag">HISTORICAL ACTUAL</span><h3>Participant costs, 2024–25</h3><div class="metric">$46.3bn</div><p class="small">Nominal accrual costs<br>Not Commonwealth-only spending</p></article><article class="card"><span class="tag">CUMULATIVE · JUNE 2026</span><h3>NDIS-related convictions</h3><div class="metric">26</div><p class="small">Since December 2022<br>Does not estimate total fraud</p></article><article class="card"><span class="tag gap">NOT ESTABLISHED HERE</span><h3>Scheme-wide fraud rate</h3><div class="metric">Unknown</div><p class="small">A prevalence estimate requires<br>a representative audit method</p></article></div><div class="split"><section class="panel"><h2>How participant costs grew</h2><p class="small">AUD billions, nominal accrual costs. Agency administration excluded.</p>${lineChart([{name:'Participant costs',values:obs.map(r=>r.value)}],obs.map(r=>r.period),{title:'NDIS actual participant costs, 2018–19 to 2024–25',zero:true})}<p class="source">${source('ndis_a')} · Table 6.11, p134.</p></section><section class="panel"><h2>What the fraud evidence tells us</h2><p>By 30 June 2026, the NDIA reported 26 convictions since December 2022. Courts had ordered $3.5m returned; $50m of assets had been seized since the taskforce’s establishment.</p><p>Orders are not cash recovered. Seized assets are not established losses. Neither total estimates all undetected fraud.</p><p class="source">${source('fraud')}</p></section></div><section class="panel"><h2>Fraud is one part of integrity</h2>${table(['Measure','What it means','Can it be extrapolated?'],[['Proven fraud','Intentional deception established through the relevant legal process.','No: detected cases are not a random sample.'],['Suspected fraud','Allegations or investigations; outcomes may be unresolved.','No: allegations are not convictions.'],['Non-compliant claims','Payments or claims that fail scheme rules, potentially without dishonest intent.','Only with a documented sampling and estimation method.'],['Administrative error / waste','Mistakes or spending that does not deliver value; definitions need stating.','Keep separate from criminal fraud.'],['Integrity leakage estimate','A broader estimate that may include several categories.','Do not label the entire amount proven fraud.']])}<p class="source">${source('ndis_f')}</p></section><section class="panel"><h2>Does NDIS spending create “government jobs”?</h2><p>A private provider’s employees can be privately employed and publicly funded. The useful additional measure is <strong>government-funded employment exposure</strong>. It supplements the official sector classification.</p>${table(['Dimension','Example','Measure'],[['Employer control','Government agency / private company / nonprofit','Public–private classification'],['Funding source','NDIS / other public contracts / private customers','Share of revenue or paid hours funded by government'],['Industry','Care, health, construction, technology','Industry classification'],['Economic outcome','Care quality, independent living, work enabled','Outcomes and value added, not employer label']])}<p class="source">${source('sector')}. Entire health and social assistance employment must not be treated as NDIS employment.</p></section><section class="panel"><h2>Test the workforce opportunity cost</h2><div class="steps"><article class="step"><b>Work drawn into care</b>Where did workers come from? Identify moves from other jobs, new workforce entry and extra hours.</article><article class="step"><b>Work enabled by care</b>Measure paid work that participants and unpaid carers can now undertake, alongside wellbeing.</article><article class="step"><b>Compare the alternative</b>Account for replacement disability services, wages, shortages, retraining and time. No support is not a neutral baseline.</article></div><p>Suggested accounting model: net change in other-sector hours = participant hours enabled + carer hours enabled − hours displaced from other employment. This is a framework; its inputs have not been estimated here.</p></section><section class="panel"><h2>How much debt is attributable to NDIS?</h2><p>There is no separately issued pool of “NDIS debt”. Compare two complete budget paths. Include the Commonwealth share, replacement services, taxes, interest and other spending decisions.</p><a href="#scenarios">Explore the financing sensitivity calculator →</a></section><section class="panel"><h2>Actuals and earlier projections</h2>${table(['Financial year','Participant cost / $bn','Status'],[...obs,...dataFor('ndis_old_projection')].map(r=>[r.period,r.value.toFixed(1),r.status]))}<div class="notice warning">The June 2025 AFSR projections above predate the 2026 Budget changes. They are historical forecast vintages, not the current-policy baseline.</div></section>`}
function scenarios(){return top('05 / Policy & scenarios','A policy forecast needs assumptions.','Compare a dated government baseline with a specified alternative, and show what changes when its assumptions change.')+`<section class="panel"><span class="tag forecast">OFFICIAL CONDITIONAL SCENARIOS</span><h2>NDIS growth: the PBO’s fiscal sensitivity</h2>${table(['PBO scenario','2036–37 spending vs baseline','Return to surplus'],[['2026–27 Budget baseline','Reference case','2034–35'],['5% NDIS growth from 2027–28','+$13.5bn in that year','2035–36'],['10% annual NDIS growth','+$68.1bn in that year','No return within the medium term']])}<p class="source">${source('pbo')}, section 5.3. These are annual spending differences, not cumulative debt differences. The PBO baseline uses the Budget’s policy and economic assumptions.</p></section><section class="panel"><h2>Current settings vs One Nation: policy mechanisms</h2><span class="tag gap">DIRECTIONAL ANALYSIS · NOT A COSTED PARTY FORECAST</span>${table(['Policy area','Baseline / comparator needed','One Nation proposal','Potential effects to test'],[['NDIS','2026 Budget reforms and actual implementation; avoid counting already-budgeted savings twice.','Means-testing and provider pay changes.','Lower spending is possible; eligibility thresholds, workforce response, service access and costs shifted to families/states determine the net result.'],['Family tax','Current individual tax schedule and transfers, matched tax year.','Income splitting for couples with a dependent child.','Can help unequal-earner couples; revenue falls before offsets; secondary earners may face changed work incentives.'],['Agency and program cuts','Program-level appropriations, commitments and replacement functions.','Claimed savings of up to $90bn annually across its wider package.','Net savings require subtracting replacement costs, lost revenue and implementation costs. Do not use the headline as a verified saving.'],['Energy, resources and housing','A complete dated government-policy register and current party policy documents.','Policy index includes resource ownership, energy-price and housing measures.','Needs a separate model of investment, supply, prices, fiscal costs and transition timing before quantification.']])}<p class="source">Party proposals: ${source('on_w')} · ${source('on_t')} · ${source('on_all')}. Potential effects are this project’s hypotheses for testing, not findings from those party documents.</p></section><section class="panel"><h2>Financing sensitivity: a transparent counterfactual</h2><p>Explore an assumed recurring net spending reduction. This does not calculate One Nation’s savings or the debt caused by NDIS.</p><div class="tools"><label>Annual net saving (AUD bn)<input id="saving" type="number" value="1" min="0" max="100" step="0.1"></label><label>Interest rate (%)<input id="interest" type="number" value="4" min="0" max="15" step="0.1"></label><label>Years<input id="debt-years" type="number" value="10" min="1" max="40"></label><label>Share used to reduce borrowing (%)<input id="debt-share" type="number" value="100" min="0" max="100"></label></div><div id="debt-result" aria-live="polite"></div><p class="small">Recurrence: debt reduction(t) = debt reduction(t−1) × (1 + interest rate) + net saving × financing share. End-year savings, fixed nominal amount, unchanged rates and no macroeconomic feedback. Net saving must already deduct replacement services and revenue effects. Other uses of the saving are not modelled.</p></section><section class="panel"><h2>Medium and long term: what can be said?</h2><p><strong>Medium term, 5–10 years:</strong> outcomes depend on whether spending reforms work, private and public investment, participation and productivity. The PBO scenarios illustrate fiscal sensitivity; they do not establish a party’s effect on growth.</p><p><strong>Long term, 20–30 years:</strong> sustained productivity differences compound. Ageing, technology, housing supply, climate and energy investment, and migration change the path. Use ranges and alternative mechanisms rather than extending a short-run growth rate indefinitely.</p><p>No quantified finding that either policy package outperforms the other is supported by this edition. A defensible comparison needs legislation status, implementation dates, fiscal costings, behavioural estimates and a common economic baseline.</p><a href="#learn">Explore long-run productivity compounding →</a></section>`}
function representatives(){return top('06 / Parliament’s experience','What work preceded public office?','A public dataset should describe careers accurately, allow mixed experience and make unknowns visible.')+`<div class="notice warning">The official roster and occupation records are populated above. Employer ownership, complete career dates and durations still need individual verification; no public/private career percentages are inferred.</div><section class="panel"><h2>A framework that allows real careers</h2>${table(['Category','Treatment'],[['Private enterprise','Employment or self-employment in a privately controlled business; identify employer and dates.'],['Public service and public corporations','Classify employer control at the time of the role; ownership may later change.'],['Political employment','Ministerial advisers, electorate staff and party employees shown separately; retain legal employer and funding source.'],['Unions and employer organisations','Separate institutional category, not automatically government employment.'],['Nonprofits, universities and professions','Identify the actual institution and employment arrangement; do not infer sector from job title.'],['Elected office','Federal, state and local office recorded separately from prior employment.'],['Unpaid work / study / unknown','Retain as separate categories. Missing evidence does not become zero experience.']])}</section><section class="panel"><h2>How the completed census should work</h2><ol><li>Freeze the serving House and Senate roster at a stated date, with chamber, party at that date and electorate or state.</li><li>Extract the Parliament biography’s pre-parliament occupations. Add other primary sources where dates or employers are missing.</li><li>Record employment spells with start and end dates, hours where known, category, source and coding explanation.</li><li>Merge overlapping intervals when calculating total years. Report date ranges where only years are known; do not invent full-time equivalents.</li><li>Publish mixed-career membership and duration measures separately, with missingness and correction records.</li></ol><p class="source">${source('aph')}. The supplied transcript raises career incentives at 40:08–43:09. Career background is descriptive evidence, not proof of policy competence or causation.</p><a class="button" href="data/career-spells-template.csv" download>Download career-spell template</a> <a class="button" href="docs/career-codebook.md">Read the coding rules</a></section>`}
function evidence(){return top('07 / Sources & scrutiny','Every conclusion needs a route back to evidence.','The supplied Diary of a CEO transcript is the starting point for questions. Official statistics and explicit models are the basis for findings.')+`<div class="coverage"><span>24 timestamped claims</span><span>${(DATA.observations.length+DATA.panel.length+DATA.extensions.length+DATA.budget.length).toLocaleString()} numeric records</span><span>38 source-country entries</span><span>38 countries with annual panel data</span></div><section class="panel"><h2>Read, download, challenge</h2><p>The source code, CSV tables, assumptions and contribution templates are prepared together. The public repository welcomes evidence corrections and alternative models.</p><div class="tools"><a class="button" href="https://github.com/benmac3/policies-not-politics">View repository</a><a class="button" href="https://github.com/benmac3/policies-not-politics/issues/new/choose">Challenge a result</a><a class="button" href="source-pack.zip" download>Download website & research source</a><a class="button" href="data/claims.csv" download>Claim register · CSV</a><a class="button" href="data/sources.csv" download>Source register · CSV</a><a class="button" href="docs/research-method.md">Research method</a></div><p class="small">To challenge a result: cite the claim ID or series, identify the source and period, explain the issue, and propose a correction or competing model. Use the GitHub issue templates to submit a correction or competing model.</p></section><section class="panel"><h2>What the interview says—and how to test it</h2><label>Search claims<input id="claim-search" type="search" placeholder="Debt, housing, Denmark, AI…"></label><div id="claims-list"></div></section><section class="panel"><h2>Official sources and policy documents</h2>${DATA.sources.map(s=>`<details><summary>${esc(s.agency)} · ${esc(s.title)}</summary><p>${esc(s.note)}</p><p><a href="${esc(s.url)}" target="_blank" rel="noopener">Open source</a> · Checked ${esc(s.retrieved)}</p></details>`).join('')}</section><section class="panel"><h2>Coverage and reproducibility</h2><p>The annual panel and parliamentary records are imported from official APIs with retained responses. Australian extensions include identified report-table extracts. Bulk OECD hourly-productivity ingestion remains blocked; the existing hourly extracts are retained separately.</p><p>Remaining gaps: full hourly-productivity coverage, several selected household/ownership/technology metrics, causal NDIS workforce estimates, independently costed party alternatives, and verified employer-sector career durations. The transcript register is representative, not a fact-check of every statement in the two-hour interview.</p><p>The public source pack contains paraphrases and a fingerprint of the supplied transcript. Its recording date and publisher link have not been verified.</p></section>`}

function australiaData(){const wanted=['NY.GDP.PCAP.PP.KD','SL.GDP.PCAP.EM.KD','FP.CPI.TOTL.ZG','SL.UEM.TOTL.ZS','SL.TLF.CACT.ZS','NE.GDI.FTOT.ZS','GB.XPD.RSDV.GD.ZS','SI.POV.GINI','EG.IMP.CONS.ZS'];return `<section class="panel"><h2>Australia: household and economic context</h2><p>Annual calendar-year series. Latest available observations have different reference years; consult the definitions before comparison.</p>${table(['Measure','Latest value','Year','Source'],wanted.map(code=>{const m=DATA.metrics.find(m=>m.code===code),r=DATA.panel.filter(r=>r.indicator===code&&r.country==='AUS').at(-1);return[esc(m.name),r?fmt(r.value)+' '+esc(m.unit):'Not available',r?.period||'—',source('wdi_'+code)]}))}<a href="#countries">Explore annual histories and international comparisons →</a></section>`}
function fiscalData(){const rows=DATA.budget.filter(r=>r.indicator==='budget_net_debt_gdp'),actual=rows.filter(r=>r.status==='Budget historical actual');return `<section class="panel"><h2>Australia’s Commonwealth net debt</h2><p>% of GDP. Historical actuals from the 2026–27 Budget, Table 11.4. State/local debt is outside this series.</p>${lineChart([{name:'Net debt / GDP',values:actual.map(r=>r.value)}],actual.map(r=>r.period),{title:'Commonwealth net debt as a share of GDP',zero:true})}<details><summary>History and Budget estimates · 2000–01 to 2029–30</summary>${table(['Year','Net debt / GDP','Net interest / GDP','Status'],rows.map(r=>[r.period,r.value.toFixed(1)+'%',DATA.budget.find(x=>x.indicator==='budget_net_interest_gdp'&&x.period===r.period).value.toFixed(1)+'%',esc(r.status)]))}</details><p class="source">${source('budget26')}</p><a href="data/budget.csv" download>Download fiscal history</a></section>`}
function ndisData(){const cost=extra('ndis_accrual'),ops=extra('ndia_operations'),parts=extra('ndis_participants').filter(r=>r.period.endsWith('-06'));return `<section class="panel"><span class="tag">UPDATED · JUNE / JULY 2026</span><h2>Participants, supports and administration</h2>${table(['Financial year','Participants at June end','Accrual supports / $bn','Agency operations / $bn'],cost.map((r,i)=>[r.period,fmt(parts[i].value),fmt(r.value),fmt(ops[i].value)]))}<p>In July 2026, the scheme had 785,089 participants. Rolling 12-month supports were $51.69bn, compared with $46.70bn a year earlier. These monthly management figures include accrued supports.</p><p class="source">${source('ndis26')} · figures 1, 29, 36; ${source('ndis_july')}</p><h3>2025–26 cash payments by support category</h3>${table(['Category','AUD million'],extra('ndis_payment_category').map(r=>[esc(r.detail),fmt(r.value)]))}<p class="small">Published total: $51,452m. Rounded categories sum to $51,451m. Cash/in-kind payments differ from accrual supports.</p><h3>Reported employment and participation outcomes</h3>${table(['Measure','At entry','Latest reassessment'],[0,2,4].map(i=>{const r=extra('ndis_outcome');return[esc(r[i].detail.split(' | ')[0]),r[i].value+'%',r[i+1].value+'%']}))}<p class="small">Survey comparisons, not causal effects: ageing, selection and other changes may contribute. They cannot establish how many jobs NDIS created or displaced.</p><a href="data/extensions.csv" download>Download observations and forecast inputs</a></section>`}
function budgetForecast(){const years=extra('budget_gdp').map(r=>r.period),ind=['budget_gdp','budget_cpi','budget_wpi','budget_unemployment','budget_gross_debt','budget_gross_debt_gdp','budget_cash_balance'];return `<section class="panel"><h2>Government baseline: Budget 2026–27</h2><p>2024–25 is the Budget’s recorded outcome; later columns are its estimates and forecasts. Retain this vintage when evaluating forecast accuracy.</p>${table(['Metric',...years],ind.map(i=>[esc(i.replace('budget_','').replaceAll('_',' '))+' · '+esc(extra(i)[0].unit),...extra(i).map(r=>fmt(r.value))]))}<p class="source">${source('budget26')} · tables 1.1–1.2. WPI and CPI are through-year June-quarter changes, GDP is annual-average growth.</p><h3>NDIS program expenses in the Budget</h3>${table(['Year','AUD billion','Basis'],extra('budget_ndis_program').map(r=>[r.period,fmt(r.value),'Budget estimate']))}<p class="small">Table 6.9.2 includes state and Commonwealth contributions and departmental program costs. It is broader than participant supports and must not be spliced onto that series.</p><p>The June 2026 WPI outcome was 3.2%, compared with the Budget’s 3.25% forecast. ${source('abs_wpi26')}</p></section>`}
function parliamentData(){const p=DATA.parliament;return `<section class="panel"><h2>${p.roster.length} parliamentarians · ${p.roster.reduce((a,r)=>a+r.occupations.length,0)} occupation records</h2><p>Official Handbook snapshot: ${esc(p.retrieved)}. Includes mixed careers. Sector hints below are provisional rules, not verified employer histories. Missing occupations remain unknown.</p><div class="tools"><label>Find a name, party, role or employer<input id="rep-search" type="search" placeholder="Name, engineer, teacher…"></label><label>Chamber<select id="rep-chamber"><option value="all">Both chambers</option><option value="Member">House</option><option value="Senator">Senate</option></select></label><a class="button" href="data/parliament.csv" download>Download occupation records · CSV</a></div><div id="rep-list"></div></section><section class="panel"><h2>Previous state or local government service</h2>${table(['Party','State','Local','Either (unique people)','Party total'],p.prior.map(r=>[esc(r.Party),r.State,r.Local,r.Total,r.TotalNumberOfMembers]))}<p class="small">Official prior-service measure; overlapping state/local careers are counted once in “either”. This is prior government service, not all public employment.</p><h3>Official occupation categories</h3>${table(['Category','Recorded count'],p.occupations.Rows.map(r=>[esc(r.Field),r.Parties.find(x=>x.Party==='Total')?.Count??'—']))}<p class="small">Categories and careers overlap. Counts are not mutually exclusive shares of parliament, nor public/private sector percentages.</p><p class="source">${source('aph_api')}</p></section>`}
function repList(){const q=$('#rep-search').value.toLowerCase(),ch=$('#rep-chamber').value;const rows=DATA.parliament.roster.filter(r=>(ch==='all'||r.chamber.includes(ch))&&[r.name,r.party,...r.occupations].join(' ').toLowerCase().includes(q));$('#rep-list').innerHTML=`<p>${rows.length} matching records</p>`+rows.map(r=>`<details><summary>${esc(r.name)} · ${esc(r.chamber)} · ${esc(r.party)}</summary><p>${esc(r.electorate||r.state)} · First federal service: ${esc(r.first_service||'Not recorded')}</p>${table(['Recorded occupation','Provisional sector hint'],r.occupations.length?r.occupations.map((o,i)=>[esc(o),esc(r.sector_hints[i])]):[['Not recorded','Unknown']])}<a href="${esc(r.source)}" target="_blank" rel="noopener">Official biography</a></details>`).join('')}
function coverageData(){return `<section class="panel"><h2>Dataset coverage and audit trail</h2>${table(['Series','Countries with any data','Observations','WDI update'],DATA.metrics.map(m=>[esc(m.name),m.countries+'/38',m.observations,esc(m.lastupdated)]))}<p>Annual values are imported without interpolation. The source register retains WDI definitions and originating agencies. Download URLs and response hashes are recorded in metrics.json; raw API responses are stored in the repository.</p><div class="tools"><a href="data/metrics.csv" download>Metric definitions and provenance</a><a href="data/panel.csv" download>Annual panel</a><a href="data/parliament.csv" download>Parliament occupations</a><a href="docs/data-release.md">Release notes and limitations</a></div></section>`}
function householdData(){const a=extra('household_income_mean'),b=extra('household_income_median');return `<section class="panel"><h2>Mean and median household income</h2><p>Weekly equivalised disposable income in 2019–20 dollars. This historical survey ends in 2019–20; it does not describe today’s household income.</p><div class="legend"><span>Mean</span><span>Median</span></div>${lineChart([{name:'Mean',values:a.map(r=>r.value)},{name:'Median',values:b.map(r=>r.value)}],a.map(r=>r.period),{title:'Historical real household income'})}${table(['Survey year','Mean / $ per week','Median / $ per week'],a.map((r,i)=>[r.period,r.value,b[i].value]))}<p class="small">Survey cycles are not equally spaced on the chart. Income standards changed in 2007–08; collection changed in 2019–20. Equivalisation adjusts for household size and composition.</p><p class="source">${source('abs_wealth')} · Graph 1.</p></section>`}
const originalDashboard=dashboard,originalLearn=learn,originalNdis=ndis,originalScenarios=scenarios,originalRepresentatives=representatives,originalEvidence=evidence;
dashboard=()=>originalDashboard()+australiaData()+householdData()+fiscalData();
learn=()=>originalLearn()+`<section class="panel"><h2>See the distinctions in measured data</h2><p>The country panel supplies separate series for total GDP growth, GDP per person and output per employed person. Compare Australia over time, then ask whether inflation, participation and investment help explain the pattern.</p>${australiaData()}<p>Output per worker reflects both hourly productivity and hours per worker. Income inequality is a distribution measure, not a measure of the size of the economy.</p></section>`;
ndis=()=>originalNdis().replace('</p>', '</p>'+ndisData());
scenarios=()=>originalScenarios()+budgetForecast();
representatives=()=>originalRepresentatives().replace('</p>', '</p>'+parliamentData());
evidence=()=>originalEvidence()+coverageData();
const pages={dashboard,learn,countries,ndis,scenarios,representatives,evidence};
function render(){const page=location.hash.slice(1)||'dashboard';$('#main').innerHTML=(pages[page]||dashboard)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));if(page==='learn'){['growth-a','growth-b','years'].forEach(id=>$('#'+id).addEventListener('input',growth));growth();$('#export-chart').onclick=()=>{const current=$('#growth-output svg');if(!current)return;const svg=current.cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','760');svg.setAttribute('height','380');svg.setAttribute('viewBox','0 0 760 380');svg.insertAdjacentHTML('beforeend','<text x="58" y="332" style="font:16px sans-serif;fill:#112b36">Illustrative productivity paths · index starts at 100</text><text x="58" y="356" style="font:14px sans-serif;fill:#112b36">'+esc($('#growth-output').dataset.caption)+'</text>');download('productivity-compounding.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml')}}if(page==='countries'){['country-search','country-scope','panel-metric','panel-year'].forEach(id=>$('#'+id).addEventListener('input',countryTable));countryTable();$('#history-country').addEventListener('input',countryHistory)}if(page==='representatives'){['rep-search','rep-chamber'].forEach(id=>$('#'+id).addEventListener('input',repList));repList()}if(page==='scenarios'){['saving','interest','debt-years','debt-share'].forEach(id=>$('#'+id).addEventListener('input',debt));debt()}if(page==='evidence'){$('#claim-search').addEventListener('input',claimList);claimList()}}
function num(id,min,max){const el=$('#'+id),v=Number(el.value);return el.value!==''&&Number.isFinite(v)&&v>=min&&v<=max?v:null}
function growth(){const a=num('growth-a',-2,5),b=num('growth-b',-2,5),n=num('years',1,40),el=$('#growth-output');if(a===null||b===null||n===null||!Number.isInteger(n)){el.innerHTML='<p>Enter growth between −2% and 5%, and a whole number of years from 1 to 40.</p>';return}const labels=Array.from({length:n+1},(_,i)=>i),av=labels.map(i=>100*(1+a/100)**i),bv=labels.map(i=>100*(1+b/100)**i);el.innerHTML=`<div class="legend"><span>Path A · ${a}% per year</span><span>Path B · ${b}% per year</span></div>${lineChart([{name:'Path A',values:av},{name:'Path B',values:bv}],labels,{title:'Illustrative output per hour, indexed to 100'})}<p>After ${n} years: <strong>${av[n].toFixed(1)}</strong> on Path A and <strong>${bv[n].toFixed(1)}</strong> on Path B. B is <strong>${Math.abs((bv[n]/av[n]-1)*100).toFixed(1)}% ${bv[n]>=av[n]?'higher':'lower'}</strong> than A.</p>`;el.dataset.caption=`A: ${a}% / year (blue); B: ${b}% / year (teal). Teaching example, not a forecast.`}
function debt(){const s=num('saving',0,100),r=num('interest',0,15),n=num('debt-years',1,40),f=num('debt-share',0,100),el=$('#debt-result');if([s,r,n,f].some(v=>v===null)||!Number.isInteger(n)){el.innerHTML='<p>Enter valid values within the stated ranges and a whole number of years.</p>';return}let d=0;const path=[0];for(let i=0;i<n;i++){d=d*(1+r/100)+s*f/100;path.push(d)}el.innerHTML=`<div class="result">$${d.toFixed(2)}bn less debt after ${n} years</div><p class="small">Conditional on your assumptions: $${(s*n*f/100).toFixed(2)}bn direct borrowing reduction plus $${(d-s*n*f/100).toFixed(2)}bn avoided interest.</p>${lineChart([{name:'Illustrative debt reduction',values:path}],path.map((_,i)=>i),{title:'Illustrative debt reduction in AUD billions',zero:true})}`}
function countryTable(){const q=$('#country-search').value.toLowerCase(),only=$('#country-scope').value==='loaded',code=$('#panel-metric').value||'NY.GDP.PCAP.PP.KD',year=$('#panel-year').value||'2024',metric=DATA.metrics.find(m=>m.code===code),all=DATA.panel.filter(r=>r.indicator===code);const rows=DATA.countries.filter(c=>c.name.toLowerCase().includes(q)||c.code.toLowerCase().includes(q)).map(c=>{const records=all.filter(r=>r.country===c.code).sort((a,b)=>a.period.localeCompare(b.period)),r=records.find(r=>r.period===year),last=records.at(-1);if(only&&!r)return null;return[esc(c.name),r?fmt(r.value):'Not available',last?last.period:'None',`<a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.agency)}</a>`]}).filter(Boolean);$('#country-table').innerHTML=`<section class="panel"><h2>${esc(metric.name)} · ${year}</h2><p>${esc(metric.unit)} · ${all.filter(r=>r.period===year).length}/38 countries available in this year.</p>${rows.length?table(['Country',esc(metric.unit),'Latest available year','National agency'],rows):'<p>No countries match.</p>'}<p class="source">${source('wdi_'+code)}</p><details><summary>Definition and originating organisations</summary><p>${esc(DATA.sources.find(s=>s.id==='wdi_'+code)?.note)}</p></details></section>`;countryHistory()}
function countryHistory(){const country=$('#history-country').value||'AUS',code=$('#panel-metric').value||'NY.GDP.PCAP.PP.KD',m=DATA.metrics.find(m=>m.code===code),records=DATA.panel.filter(r=>r.country===country&&r.indicator===code).sort((a,b)=>a.period.localeCompare(b.period));const years=Array.from({length:26},(_,i)=>String(2000+i)),values=years.map(y=>records.find(r=>r.period===y)?.value??null);$('#country-history').innerHTML=records.length?`<h3>${esc(names[country])} · ${esc(m.name)}</h3><p class="small">${esc(m.unit)}. Breaks in the line indicate missing years.</p>${lineChart([{name:m.name,values}],years,{title:names[country]+' '+m.name})}<details><summary>Annual values (${records.length})</summary>${table(['Year',esc(m.unit)],records.map(r=>[r.period,fmt(r.value)]))}</details>`:'<p>No values available for this country and measure.</p>'}
function claimList(){const q=$('#claim-search').value.toLowerCase(),rows=DATA.claims.filter(c=>JSON.stringify(c).toLowerCase().includes(q));$('#claims-list').innerHTML=rows.length?rows.map(c=>`<details><summary>${esc(c.id)} · ${esc(c.indicator)} <span class="small">${esc(c.timestamp)}</span></summary><p><strong>Transcript claim (paraphrased):</strong> ${esc(c.claim)}</p><span class="tag gap">${esc(c.verdict)}</span><p>${esc(c.assessment)}</p>${c.source?`<p class="source">${source(c.source)}</p>`:''}</details>`).join(''):'<p>No claims match your search.</p>'}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
